def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def carrot(a):return I('carrot',a,'g','carrots, peeled and trimmed','Use the same weight of a different carrot variety; color and sweetness will change.')
def butter(a):return I('butter',a,'g','unsalted butter','Use the same weight of a block-style dairy-free butter alternative.')
def stock(a):return I('stock',a,'ml','unsalted prepared beef stock','Use the same volume of unsalted vegetable stock for a different flavor; check other ingredients before treating the whole recipe as vegetarian.')
def onion(a):return I('onion',a,'g','peeled onion','Use the same weight of trimmed leek, rinsing away any grit.')
def salt(a=3):return I('salt',a,'g','fine salt','Reduce or omit, especially if using salted stock.')
def pepper():return I('pepper',.25,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def cayenne():return I('cayenne',.125,'tsp','ground cayenne pepper','Omit for a milder soup.')
def sugar(a):return I('sugar',a,'g','granulated sugar','Omit for a less sweet soup.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water; water for dough or starch slurry should remain cold.')
def flour(a):return I('flour',a,'g','all-purpose flour','For a sauce, use the same weight of a gluten-free blend labeled for sauces; pastry requires a separate tested gluten-free dough.')
def bread(a):return I('bread',a,'g','plain bread','Use the same weight of gluten-free bread suitable for toasting.')
def oil(a,k='oil'):return I(k,a,'ml','neutral vegetable oil','Use the same volume of refined sunflower or rapeseed oil.')
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g pasteurized liquid yolk per large yolk; omitting yolk changes the recipe.')
def cream(a):return I('cream',a,'ml','heavy cream','Use the same volume of unsweetened plant cream suitable for cooking.')
def celery(a):return I('celery',a,'g','trimmed celery stalks','Use the same weight of peeled celeriac, cut small and cooked until tender.')
def turnip(a):return I('turnip',a,'g','peeled turnip','Use the same weight of peeled rutabaga; allow extra cooking time until tender.')
def add(n,title,y,t,desc,items,steps,notes):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Soups',servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T18:00:00Z',notes=notes+' Missing amounts, yields and timings are modern adaptation estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes quantities, not cooking times. Cool leftovers promptly in shallow containers and refrigerate within 2 hours at 4°C (40°F) or colder.',source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
PUREE='Press the vegetables and their liquid through a coarse sieve into a clean saucepan, or use an immersion blender directly in the deep pan with its head submerged. Do not seal hot soup in a countertop blender.'
r=add(1,'Carrot Soup with Light Bone Stock',10,80,'A light, thin carrot soup with a little butter and sugar, simmered slowly and passed through a sieve.',[carrot(600),butter(28),sugar(4),salt(5),pepper(),stock(3000)],['Slice {{carrot}} thinly. Melt {{butter}} in a large saucepan, add the carrots, {{sugar}}, {{salt}} and {{pepper}}, and stir over medium-low heat for 5 minutes without browning.','Add {{stock}}, bring to a simmer and cook gently for 1 hour, partly covered, until the carrots are very tender.',PUREE,'Return to a gentle boil, stir well and serve. This is a thin stock-based soup, not a thick carrot purée.'],'Six carrots become 600 g prepared carrot. The source three quarts is standardized to a modern 3 L batch, not claimed as an exact historical quart conversion. Its light stock-to-carrot ratio is retained.')
r=add(11,'Sieved Carrot Soup with Fried Bread',4,55,'Smooth carrot pulp is stirred into stock with cayenne and served with crisp fried bread squares.',[carrot(350),water(1000),stock(1000),salt(2),cayenne(),bread(80),oil(20)],['Slice {{carrot}} into 1 cm rounds. Bring {{water}} to a boil in a saucepan, add the carrots and simmer for 20–30 minutes until very soft. Drain well.','Press all the cooked carrots through a sieve, retaining the pulp for the soup.','Gradually whisk {{stock}} into the pulp with {{salt}} and {{cayenne}}. Bring to a gentle simmer and cook for 5 minutes.','Cut {{bread}} into 1 cm cubes. Heat {{oil}} in a skillet and fry the cubes for 4–6 minutes, turning often, until crisp and golden. Drain on a rack and serve alongside the hot soup.'],'The carrot count and weighed pulp describe the same ingredient, not two additions. The modern recipe uses the whole peeled carrot instead of discarding the core. The modern 350 g prepared raw carrot replaces the source 12–13 ounces of cooked outer-flesh pulp; this is a disclosed practical adjustment, not an exact yield equivalence. The quart becomes 1 L and the missing fried-bread component is supplied.')
r=add(13,'Cream of Grated Carrot Soup',6,50,'Finely grated carrots simmer with onion and bay before milk and a little starch create a light creamy soup.',[carrot(300),water(500),onion(20),I('bay',1,'','dried bay leaf','Omit if unavailable.'),I('milk',1000,'ml','whole milk','Use the same volume of unsweetened soy milk; flavor differs.'),I('starch',8,'g','cornstarch','Use 8 g potato starch and avoid prolonged boiling.'),water(30,'slurry'),salt(),pepper(),butter(28)],['Finely grate {{carrot}}. Put in a saucepan with {{water}}, {{onion}} kept as one thick slice and {{bay}}. Cover and simmer for 30 minutes until tender.','Lift out and discard the onion slice and bay leaf. Stir in {{milk}} and heat gently until steaming.','Mix {{starch}} with {{slurry}} until smooth. Stir into the soup with {{salt}} and {{pepper}}. Bring to a gentle simmer and stir for 1 minute until lightly thickened.','Stir in {{butter}} immediately before serving.'],'Three carrots become 300 g; the source pint and quart become modern 500 ml and 1 L quantities. The missing slurry water is explicit. Grated texture is retained rather than turning this into a different blended soup.')
r=add(26,'Sopa de Zanahorias with Fried Pastry and Chayote',4,65,'Carrots, chayote, peas and cheese are layered with small fried yolk pastries, then moistened with hot broth.',[flour(113),yolks(3),water(20),salt(1),butter(14),oil(350,'fryoil'),carrot(250),I('chayote',200,'g','young chayote, peeled and seed removed','Use 200 g zucchini; simmer only 4–6 minutes until tender.'),I('peas',100,'g','frozen green peas','Use the same weight of fresh shelled peas and cook until tender.'),stock(1200),I('cheese',50,'g','grated mild firm cheese','Use the same weight of a firm dairy-free cheese that suits your needs, or omit.'),pepper(),I('parsley',5,'g','fresh parsley, finely chopped','Use the same weight of cilantro for a different flavor.')],['Mix {{flour}}, {{yolks}}, {{salt}} and softened {{butter}}. Add {{water}} a little at a time, only as needed to make a firm pliable dough. Knead for 15 minutes, cover and rest for 15 minutes.','Meanwhile, cut {{carrot}} and {{chayote}} into 1 cm cubes. Bring {{stock}} to a simmer, add both vegetables and cook for 12–18 minutes until tender. Add {{peas}} for the final 3–5 minutes. Lift out the vegetables with a slotted spoon, keeping the broth hot.','Roll the rested dough about 2 mm thick between sheets of baking parchment and cut into small 3 cm shapes.','Put {{fryoil}} in a heavy narrow saucepan, no more than one-third full. Heat to 175°C (347°F). Fry the pastry in small batches for 2–3 minutes, turning, until golden and cooked through. Drain on a rack. Do not leave hot oil unattended.','Divide half the fried pastry among heatproof serving bowls. Layer with {{cheese}}, the cooked carrot and chayote, then the remaining pastry and peas.','Bring the reserved broth back to a simmer, stir in {{pepper}} and {{parsley}}, and ladle over the layers. Serve immediately while some pastry remains crisp.'],'The source fried pastry and layered presentation are retained. Vegetable, stock, cheese and frying amounts are supplied; oil replaces the source frying lard. The 350 ml oil is a cooking medium, not all consumed. Water is a maximum dough allowance; yolk size and flour absorption vary.')
r=add(31,'Sopa de Sustancia de Zanahoria (Carrot Essence Soup)',6,150,'Carrots slowly simmer in broth with a little lard and sugar, producing a light strained soup poured over toast.',[carrot(800),I('lard',30,'g','food-grade lard','Use 30 g unsalted butter or neutral vegetable oil.'),stock(2000),sugar(6),bread(120)],['Chop {{carrot}} finely. Heat {{lard}} in a large saucepan and sauté the carrots for 5 minutes, stirring.','Add {{stock}} and {{sugar}}. Cover loosely and simmer very gently for at least 2 hours until the carrots are falling apart. Add small splashes of water if evaporation exposes the carrots.','Strain through a fine sieve, pressing gently to extract liquid but leaving most solids behind. Reserve the carrot solids for another use. Return the strained soup to a saucepan and bring to a gentle boil; skim any foam. It should remain thin.','Toast {{bread}} until crisp, cut into pieces and divide among heatproof bowls. Pour the hot soup over the toast and serve.'],'A smaller eight-carrot equivalent batch replaces the source 30–40 carrots. The undefined quarter of lard and broth quantity become explicit modern amounts. Straining with most pulp held back is a disclosed interpretation of the source thin carrot essence; the original wording is preserved separately.')
r=add(48,'Gulerod-Suppe with Browned Roux and Croutons',10,65,'Carrots and onions simmer with a herb bundle, then a browned butter-and-flour roux lightly thickens the strained soup.',[carrot(500),onion(225),stock(2500),I('parsley',5,'g','fresh parsley stalks','Use the same weight of fresh celery leaves.'),I('thyme',2,'g','fresh thyme sprigs','Use 0.25 tsp dried thyme in a tied food-safe spice bag.'),I('bay',1,'','dried bay leaf','Omit if unavailable.'),salt(),dict(pepper(),name='ground white pepper'),butter(50),flour(50),bread(150),oil(20)],['Slice {{carrot}} and {{onion}}. Tie {{parsley}}, {{thyme}} and {{bay}} in a food-safe herb bundle or bag. Put all in a saucepan with {{stock|0.4}}, {{salt}} and {{pepper}}. Simmer, partly covered, for 30–40 minutes until very soft.','Remove and discard the herb bundle. Press the vegetables and cooking liquid through a coarse sieve into a bowl.','In the emptied saucepan, melt {{butter}}, stir in {{flour}} and cook over medium-low heat for 4–6 minutes, stirring, until light golden brown. Do not let it burn.','Remove briefly from the heat and gradually whisk in the strained vegetable mixture and {{stock|0.6}}. Return to a simmer and cook for 8–10 minutes, stirring, until smooth and lightly thickened.','While the soup finishes, cut {{bread}} into cubes, toss with {{oil}} and bake on a tray at 180°C (356°F) for 10–15 minutes, turning once, until crisp. Serve the croutons alongside.'],'Two matching transcriptions are consolidated. The mistranslated whisk is a herb bundle. The original 2 L initial broth belongs within the 5 L total; it is not additional. This half batch uses 1 L first and 1.5 L later. Explicit source grams take precedence over corrupt skein/quintal parentheticals. Missing crouton instructions are supplied.')
r['sourceAliases']=[rows[49]['id']];r['source']+=' Equivalent source retained: '+src(49)['recipe']['source']
r=add(50,'Gulerod-Suppe Thickened with Rice Flour',8,80,'Whole carrots are cooked in meat stock, sieved and lightly thickened with rice flour, with toast served alongside.',[carrot(800),stock(2000),I('riceflour',60,'g','finely ground white rice flour','Use the same weight of brown rice flour; flavor and texture differ.'),water(120,'slurry'),salt(),bread(160)],['Put {{carrot}} in a saucepan with {{stock}} and {{salt}}. Keep small carrots whole; halve very thick ones lengthwise. Cover and simmer for 40–60 minutes until very tender.',PUREE,'Mix {{riceflour}} with {{slurry}} until smooth. Whisk into the simmering soup and cook gently for 8–10 minutes, stirring, until the flour is cooked and the soup lightly thickened.','Toast {{bread}} until crisp and serve alongside.'],'The source half-pint of rice flour is not treated as a reliable mass conversion: 60 g is an explicit modern thickening choice. Stock, salt and toast amounts are supplied. Its separate browned-vegetable and white-root method remains a complete named variation instead of being mixed into this base.')
items=[carrot(20),onion(10),butter(25),stock(1500),I('parsnip',150,'g','peeled parsnip, diced 1 cm','Use the same weight of peeled parsley root.'),turnip(150),I('celeriac',150,'g','peeled celeriac, diced 1 cm','Use the same weight of peeled turnip.'),I('meatballs',250,'g','fully cooked small meatballs, refrigerated','Use the same weight of fully cooked vegetarian balls; follow their heating directions.'),salt()]
steps=['Finely chop {{carrot}} and {{onion}}. Melt {{butter}} in a saucepan and cook the vegetables for 5–7 minutes until lightly browned.','Add {{stock}} and {{salt}}, then simmer for 15–20 minutes until the carrot can be mashed. Press through a fine sieve and return the strained broth to the pan.','Add {{parsnip}}, {{turnip}} cut into 1 cm dice and {{celeriac}}. Simmer for 15–20 minutes until tender.','Add {{meatballs}} and heat according to their package instructions until piping hot throughout, at least 74°C (165°F). Serve with the diced roots in the broth.']
