r=add(75,'Carrot and Celery Soup with Lemon',6,55,'Grated carrots, celery and onion make a vegetable-rich soup finished with a small squeeze of lemon.',[carrot(600),celery(200),onion(150),dict(stock(1000),name='unsalted prepared vegetable stock'),salt(),pepper(),I('lemon',10,'ml','lemon juice','Use 10 ml mild wine vinegar for the source alternative.')],['Grate {{carrot}} coarsely. Thinly slice {{celery}} and {{onion}}. Put in a large saucepan with {{stock}}, {{salt}} and {{pepper}}.','Bring to a simmer, cover and cook for 30–40 minutes until all vegetables are very tender.',PUREE,'Return to a gentle simmer, stir in {{lemon}} and serve.'],'This half-sized adaptation uses the whole peeled carrot rather than discarding the core. Celery heads and missing seasonings become explicit modern weights. Vegetable stock is chosen for this version; no certification or dietary suitability of purchased ingredients is implied.')
def finnish(n,title,car,sto,oni,cel,tur,sug,serv):
 items=[carrot(car),onion(oni),celery(cel),butter(28),stock(sto),flour(16),yolks(2),cream(240),salt(),pepper()]+([turnip(tur)] if tur else [])+([sugar(sug)] if sug else [])
 steps=['Cut {{carrot}}, {{onion}} and {{celery}}'+(' and {{turnip}}' if tur else '')+' into small pieces. Melt {{butter|0.5}} in a large saucepan and cook the vegetables with {{salt}}'+(' and {{sugar}}' if sug else '')+' for 8–10 minutes, stirring, until lightly browned.','Add {{stock}} and {{pepper}}, bring to a simmer and cook for 25–35 minutes until the vegetables are very soft.',PUREE,'In a separate small pan, melt {{butter|0.5}}. Stir in {{flour}} and cook for 2 minutes. Whisk in several ladlefuls of hot soup until smooth, then stir this mixture back into the main pan. Simmer for 5 minutes.','Whisk {{yolks}} with {{cream}} in a bowl. Gradually whisk in several spoonfuls of hot soup. Reduce the soup to low heat and slowly stir the egg mixture into it.','Cook gently, stirring, until the soup reaches 71°C (160°F). Do not boil after adding the egg mixture. Serve immediately.']
 r=add(n,title,serv,70,'Light carrot and '+('turnip' if tur else 'celery')+' soup is sieved, lightly thickened with flour and finished with a cooked egg-yolk and cream liaison.',items,steps,'Modern liquid volumes replace quarts/cups. The '+str(car)+' g carrot quantity retains this source version\'s light vegetable-to-stock ratio. The source uses butter in two stages without separately accounting for it; the listed 28 g is divided equally. This is distinct from the other Finnish-source formula. Egg heating is made explicit.');r['source']+=' Reference: https://www.fda.gov/food/buy-store-serve-safe-food/what-you-need-know-about-egg-safety';return r
